'use strict';
const courses=[
{id:'foundations',title:'Trading foundations',topic:'Foundations',level:'Beginner',format:'Reading',duration:18,desc:'Understand how markets work and get comfortable with the language of trading.',prereq:'No prior knowledge',outcomes:['Explain the difference between buying and selling.','Identify common costs and basic order types.','Recognise that trading involves the risk of loss.'],lessons:[['What is trading?','Trading means buying or selling an instrument as its price changes. A decision starts with understanding what you are trading and why its price might move.','Price changes create both opportunities and losses. A positive outcome on one trade does not prove that a decision process is reliable.'],['Orders and execution','A market order seeks execution at the available market price. A limit order specifies a price or better, but may not execute.','Execution depends on market conditions. The price you see and the price you receive may differ, particularly when prices move quickly.'],['Costs and terminology','The spread is the difference between the quoted buying and selling prices. Other costs may apply depending on the product and account.','Before any decision, check which costs apply and how they affect the position. Review the product and account information instead of assuming that every instrument works the same way.']]},
{id:'risk',title:'Understanding risk',topic:'Risk management',level:'Beginner',format:'Reading',duration:21,desc:'Explore exposure, position size and the importance of planning for losses.',prereq:'Trading foundations',outcomes:['Explain how exposure affects a potential loss.','Recognise the limits of protective orders.','Identify when more practice is appropriate.'],lessons:[['Exposure and leverage','Exposure describes the size of a market position. Leverage allows exposure larger than the funds committed as margin, amplifying the effect of price changes.','Using more leverage can magnify losses as well as gains. Available buying power is not the same as an appropriate amount of risk.'],['Planning for a loss','Consider the consequences of an adverse price move before a trade. Position size, market movement and execution all influence the outcome.','A stop order can support a plan, but does not guarantee a particular execution price. Review the product terms and how orders behave.'],['A decision to pause','A plan can include conditions for doing nothing. Uncertainty, unfamiliar products or misunderstood costs are reasons to revisit the learning material.','Practice can reveal gaps in understanding. A demo outcome cannot guarantee a similar outcome in live trading.']]},
{id:'markets',title:'Reading a market',topic:'Market analysis',level:'Beginner',format:'Video',duration:24,desc:'Learn to describe price movement and ask better questions about a chart.',prereq:'Trading foundations',outcomes:['Describe what a chart displays.','Separate an observation from a prediction.','State uncertainty in an interpretation.'],lessons:[['Reading price charts','A price chart shows historical prices over a selected period. The interval and chart type change what information is visible.','Historical patterns do not guarantee future price movement. Be precise about the time period you are observing.'],['Trends and ranges','A trend describes directional movement over a period. A range describes prices moving within an observed band.','The same market can look different over different time periods. Describe the evidence rather than treating a label as a prediction.'],['A market hypothesis','A hypothesis is a possible explanation or expectation that can be examined. It should include the evidence and what would contradict it.','Considering alternative outcomes helps distinguish analysis from certainty.']]},
{id:'plan',title:'Building a trading plan',topic:'Trading process',level:'Intermediate',format:'Reading',duration:27,desc:'Turn scattered ideas into a clear process you can review and refine.',prereq:'Understanding risk',outcomes:['Identify the decisions a plan should cover.','Record reasoning separately from results.','Choose one process improvement.'],lessons:[['Define your process','A plan records the conditions you consider, the risks you understand and the actions you intend to take.','It should also state when to pause. A written plan is useful only when you compare decisions against it.'],['Keep a decision journal','A journal records what you expected, why you made a decision and what happened.','Record both the reasoning and outcome. A favourable result can follow a poor decision, and a sound process can still experience losses.'],['Review your decisions','Review a series of decisions for recurring patterns in behaviour. Look at whether the plan was followed and which assumptions need more work.','Choose a specific change to practise and review. Avoid claiming certainty from a small number of outcomes.']]},
{id:'psychology',title:'Trading psychology',topic:'Trading process',level:'Intermediate',format:'Video',duration:18,desc:'Recognise the influence of emotion, confidence and recent outcomes.',prereq:'Understanding risk',outcomes:['Recognise common reactions to wins and losses.','Distinguish confidence from evidence.','Identify a pause-and-review habit.'],lessons:[['Emotions and decisions','Strong emotions can change how people interpret information or act on a plan. Recognising this influence is a useful first step.','A journal can help you notice circumstances that repeatedly affect your choices.'],['Confidence and evidence','Confidence is a feeling about your understanding. Evidence comes from what you can explain and apply consistently.','Check confidence against unfamiliar examples. Feeling certain does not remove market uncertainty.'],['Pause and review','A deliberate pause can give you time to revisit the reasoning behind a decision.','Review your plan and what you know before acting. More activity is not automatically better learning.']]},
{id:'select',title:'Getting to know Axi Select',topic:'Axi Select',level:'All levels',format:'Reading',duration:15,desc:'Explore the account model and the questions to clarify before considering the program.',prereq:'An understanding of trading risk',outcomes:['Distinguish educational progress from program eligibility.','Identify which official requirements to review.','Recognise the need for current program information.'],lessons:[['Learning and eligibility','Academy progress shows which lessons you have completed. Official program eligibility depends on the applicable account and program requirements.','Course completion, coins or a certificate do not grant entry to Axi Select.'],['Understanding the accounts','Before considering Select, review the official explanation of the personal trading account and allocation account, including which measures apply to each.','Use the current program information for your location. This sample lesson does not calculate eligibility or account performance.'],['Questions before you continue','Clarify availability, account requirements, costs, risks, progression and the consequences of breaching program rules.','If anything is unclear, pause and seek current information through official Axi channels. Learning is one part of an informed decision.']]}
];
courses.push(...[{"id": "backtesting", "title": "Introduction to backtesting", "topic": "Trading process", "level": "Intermediate", "format": "Reading", "duration": 30, "desc": "Learn how historical testing can inform a review and where its limitations lie.", "prereq": "Understanding risk", "membersOnly": true, "outcomes": ["Define a test.", "Consider the assumptions.", "Review the limitations."], "lessons": [["Define a test", "Write down the question you want to explore before examining historical data. Keep the assumptions and rules explicit.", "A clear test question helps you avoid changing the rules to fit a result."], ["Consider the assumptions", "Historical tests depend on data quality, costs and execution assumptions. Record these alongside any results.", "A simulation cannot reproduce every condition of live trading."], ["Review the limitations", "Compare results across different periods and record uncertainty. Look for signs that the approach depends on a narrow set of conditions.", "Historical results do not guarantee future outcomes."]]}, {"id": "journal", "title": "Building a decision journal", "topic": "Trading process", "level": "Intermediate", "format": "Reading", "duration": 24, "desc": "Use a structured journal to reflect on reasoning, behaviour and outcomes.", "prereq": "Understanding risk", "membersOnly": true, "outcomes": ["Record the decision.", "Look for patterns.", "Choose an improvement."], "lessons": [["Record the decision", "Write down the context, reasoning and uncertainties behind a decision. Make the record before you know the outcome.", "An outcome alone does not explain the quality of the reasoning."], ["Look for patterns", "Review several entries and compare the decisions with the process you intended to follow.", "Avoid drawing strong conclusions from a small number of examples."], ["Choose an improvement", "Identify one repeated process issue and define a practical way to review it in future entries.", "A journal supports reflection rather than guaranteeing performance."]]}, {"id": "economic-events", "title": "Understanding economic events", "topic": "Market analysis", "level": "Intermediate", "format": "Reading", "duration": 27, "desc": "Explore economic releases, expectations and uncertainty around market events.", "prereq": "Understanding risk", "membersOnly": true, "outcomes": ["Read an event calendar.", "Compare expectations.", "Review the context."], "lessons": [["Read an event calendar", "A calendar groups scheduled releases by date and time. Check the timezone and the meaning of each event.", "A scheduled release is information, not an instruction to trade."], ["Compare expectations", "Market participants can compare a release with prior results and expectations. Reactions depend on the broader context.", "An apparent surprise does not imply a predictable price move."], ["Review the context", "Record the information available before and after an event. Note the uncertainty and what you still need to understand.", "Volatility and execution conditions can change around an event."]]}, {"id": "scenario-review", "title": "Risk scenario workshop", "topic": "Risk management", "level": "Intermediate", "format": "Reading", "duration": 21, "desc": "Practise identifying missing information and explaining risk in sample scenarios.", "prereq": "Understanding risk", "membersOnly": true, "outcomes": ["Identify the exposure.", "Explore an adverse outcome.", "Explain your reasoning."], "lessons": [["Identify the exposure", "Begin a scenario by identifying the instrument and the size of the exposure. List the information that is missing.", "Do not infer risk from the margin amount alone."], ["Explore an adverse outcome", "Consider what could happen if the market moves against the scenario. Account for costs and uncertain execution.", "Protective orders have limitations that must be understood."], ["Explain your reasoning", "Explain the assumptions behind your assessment and identify a reason to pause for more information.", "Recognising uncertainty is part of an informed decision."]]}]);
function availableCourses(){return courses.filter(c=>!c.membersOnly||loggedIn);}
const KEY='axi-academy-visitor-user-v2';
let loggedIn=false;
let state={done:[],started:[],last:null};
let storageAvailable=true;
function demoState(){return {done:['foundations:0'],started:['foundations'],last:{course:'foundations',lesson:1}};}
function login(){
 loggedIn=true;
 state=demoState();
 try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&Array.isArray(saved.done)&&Array.isArray(saved.started)){
 state={done:saved.done.filter(v=>typeof v==='string'),started:saved.started.filter(v=>courses.some(c=>c.id===v)),last:saved.last};
 if(!courses.some(c=>c.id===state.last?.course))state.last={course:'foundations',lesson:1};
 }}catch(e){storageAvailable=false;}
 save();history.replaceState(null,'','#home');render();
}
function logout(){loggedIn=false;state={done:[],started:[],last:null};history.replaceState(null,'','#home');render();}
const main=document.querySelector('main');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const count=c=>c.lessons.filter((_,i)=>state.done.includes(c.id+':'+i)).length;
const percent=c=>Math.round(count(c)/c.lessons.length*100);
const next=c=>{let i=c.lessons.findIndex((_,i)=>!state.done.includes(c.id+':'+i));return i<0?0:i;};
function save(){if(!loggedIn)return;try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageAvailable=false;notify('Progress cannot be saved in this browser. It will last for this visit only.');}}
function notify(t){let n=document.querySelector('#notice');n.textContent=t;n.classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>n.classList.remove('visible'),4500);}
function metadata(c){return `<div class="meta"><span>${c.level}</span><span>${c.duration} min</span><span>${c.format==='Video'?'Video outline':c.format}</span></div>`;}
function card(c){return `<a class="card course-card" href="#course/${c.id}"><div class="media" aria-hidden="true">${String(courses.indexOf(c)+1).padStart(2,'0')}</div><div class="course-inner">${loggedIn?'':'<span class="tag">Free Course</span>'}<h3>${c.title}</h3>${metadata(c)}<p>${c.desc}</p><div class="card-end"><span>${c.lessons.length} lessons</span><span>${state.started.includes(c.id)?percent(c)+'% complete':'View course'}</span></div></div></a>`;}
function heading(k,t,p){return `<div class="page-heading"><p class="eyebrow">${k}</p><h1>${t}</h1>${p?`<p>${p}</p>`:''}</div>`;}
function resume(){if(!loggedIn)return '';let c=courses.find(c=>c.id===state.last?.course);if(!c)return '';let i=Number.isInteger(state.last?.lesson)&&state.last.lesson>=0&&state.last.lesson<c.lessons.length?state.last.lesson:next(c);return `<div class="resume"><div><p class="eyebrow">CONTINUE LEARNING</p><h3>${c.title}</h3><p>${c.lessons[i][0]}</p><progress value="${count(c)}" max="${c.lessons.length}" aria-label="Course progress"></progress><span class="small">${count(c)} of ${c.lessons.length} lessons completed</span></div><a class="button secondary" href="#lesson/${c.id}/${i}">Resume lesson</a></div>`;}
function instructor(){return `<div class="instructor"><div class="avatar" aria-hidden="true">AA</div><div><h3>Meet your instructor</h3><p>Instructor profile to be added</p><p class="small">Name, teaching background and credentials will appear here.</p></div></div>`;}
function selectNudge(c){return `<div class="select-nudge"><h3>Keep your learning progress</h3><p>Join Axi Select to save your progress, complete knowledge checks and pick up where you left off.</p><a class="button" href="#join-select/${c.id}">Join Axi Select</a><p class="small">Already have an account? <button class="plain-button" data-course-login="${c.id}">Login</button></p></div>`;}
function nextWebinarHighlight(){const w=webinars.filter(w=>!isRecording(w)&&new Date(w.date)>new Date()).sort((a,b)=>new Date(a.date)-new Date(b.date))[0];return `<section><div class="section-head"><h2>Your next webinar</h2><a class="text-link" href="#webinars">View all webinars</a></div>${w?`<div class="sample"><div><p class="eyebrow">${w.topic.toUpperCase()}</p><h3>${w.title}</h3><p>${webinarDate(w)} · ${webinarTime(w)} · ${w.minutes} min</p><p class="small">With ${w.instructor}</p></div><div><a class="button secondary" href="#webinar/${w.id}">${isRegistered(w)?'View registration':'View webinar'}</a></div></div><p class="small" style="margin-top:12px">Sample webinar schedule.</p>`:`<div class="card"><h3>More sessions are on the way</h3><p>Explore past webinar recordings while the next session is being scheduled.</p><a href="#webinars?view=recordings">Browse recordings</a></div>`}</section>`;}
function competitionHighlight(){return `<section><div class="section-head"><h2>Axi Select competition</h2></div><div class="sample"><div><p class="eyebrow">COMPETITION INFORMATION</p><h3>Explore the next competition</h3><p>Find the entry requirements, schedule and participation rules in one place.</p><p class="small">Competition details are placeholders and have not been announced in this prototype.</p></div><a class="button secondary" href="#select-competition">View competition information</a></div></section>`;}
function competitionPage(){return `${heading('AXI SELECT','Competition information','Review the details before deciding whether to participate.')}<div class="card"><h2>Details to be announced</h2><dl class="competition-facts"><div><dt>Dates and registration period</dt><dd>To be confirmed</dd></div><div><dt>Eligibility and entry requirements</dt><dd>To be confirmed</dd></div><div><dt>Format, rules and scoring</dt><dd>To be confirmed</dd></div><div><dt>Prizes and terms</dt><dd>To be confirmed</dd></div></dl><p class="small">This is a design placeholder, not an active competition or an invitation to trade. No entry or funding action is available.</p></div><p style="margin-top:24px"><a href="#home">Back to overview</a></p>`;}
function courseLogin(id){login();history.replaceState(null,'','#course/'+id);render();}
function home(){return `${heading('LEARN AT YOUR OWN PACE','A place to start.<br>A path to keep learning.','Explore trading essentials, build your understanding and choose what to learn next.')}<div style="margin-top:-16px;margin-bottom:36px"><a class="button" href="#catalog">Explore courses</a></div>${resume()}<section><div class="section-head"><h2>Choose your starting point</h2><span class="small">Learning paths</span></div><div class="grid"><a class="card" href="#catalog?path=beginner"><span class="path-number">01 / BEGINNER</span><h3>New to trading</h3><p>Start with the basics, then explore risk and market analysis.</p><div class="card-end"><span>3 courses</span><span>63 min</span></div></a><a class="card" href="#catalog?path=process"><span class="path-number">02 / INTERMEDIATE</span><h3>Build consistency</h3><p>Develop a plan, examine your decisions and reflect on your process.</p><div class="card-end"><span>2 courses</span><span>45 min</span></div></a><a class="card" href="#course/select"><span class="path-number">03 / ALL LEVELS</span><h3>Understand Axi Select</h3><p>Explore the account model and what to clarify about the program.</p><div class="card-end"><span>1 course</span><span>15 min</span></div></a></div></section>${loggedIn?nextWebinarHighlight():`<section><div class="section-head"><h2>Try a sample lesson</h2></div><div class="sample"><div class="sample-visual" aria-hidden="true">Aa</div><div class="sample-copy"><p class="eyebrow">TRADING FOUNDATIONS</p><h3>What is trading?</h3><p>A short introduction to markets and the decisions behind a trade. Start here, with no account required.</p><div class="meta"><span>Beginner</span><span>6 min</span><span>Reading</span></div><a class="button secondary" href="#lesson/foundations/0">Open sample lesson</a></div></div></section>`}${loggedIn?competitionHighlight():''}<section><div class="section-head"><h2>Explore the course library</h2><a class="text-link" href="#catalog">View all courses</a></div><div class="grid">${courses.slice(0,3).map(card).join('')}</div></section>${loggedIn?`<section><div class="section-head"><h2>More courses for Academy members</h2><a class="text-link" href="#catalog">View all courses</a></div><div class="grid">${courses.filter(c=>c.membersOnly).map(card).join('')}</div></section>`:''}<section>${instructor()}</section>`;}
function catalog(params){let path=params.get('path');return `${heading('COURSE LIBRARY',path==='beginner'?'New to trading':path==='process'?'Build consistency':'Find your next course',path?'Follow the recommended sequence or choose a course to explore.':'Explore lessons by topic, experience level and time commitment.')}<form class="filters" id="filters" role="search"><div><label for="search">Search courses</label><input type="search" id="search" placeholder="Search a topic or course" value="${esc(params.get('q')||'')}"></div><div><label for="topic">Topic</label><select id="topic"><option value="">All topics</option>${[...new Set(availableCourses().map(c=>c.topic))].map(t=>`<option${params.get('topic')===t?' selected':''}>${t}</option>`).join('')}</select></div><div><label for="level">Level</label><select id="level"><option value="">All levels</option><option${params.get('level')==='Beginner'?' selected':''}>Beginner</option><option${params.get('level')==='Intermediate'?' selected':''}>Intermediate</option></select></div></form><div class="results-info"><span id="result-count" role="status"></span><button class="plain-button" id="reset-filters">Clear filters</button></div><div id="results" class="grid"></div><p class="small" style="margin-top:24px">Video courses contain sample lesson outlines. Video recordings have not been added to this prototype.</p>`;}
function filterCourses(){const p=new URLSearchParams(location.hash.split('?')[1]||'');let q=document.querySelector('#search').value.trim().toLowerCase(),t=document.querySelector('#topic').value,l=document.querySelector('#level').value;let list=availableCourses().filter(c=>(!q||(c.title+' '+c.desc+' '+c.topic).toLowerCase().includes(q))&&(!t||c.topic===t)&&(!l||c.level===l)&&(!p.get('path')||(p.get('path')==='beginner'?['foundations','risk','markets'].includes(c.id):['plan','psychology'].includes(c.id))));document.querySelector('#results').innerHTML=list.length?list.map(card).join(''):'<div class="empty"><h2>No courses found</h2><p>Try another search or clear your filters.</p></div>';document.querySelector('#result-count').textContent=`${list.length} ${list.length===1?'course':'courses'}`;['q','topic','level'].forEach((key,i)=>{let v=[document.querySelector('#search').value,t,l][i];v?p.set(key,v):p.delete(key)});history.replaceState(null,'','#catalog'+(p.size?'?'+p:''));}
function detail(c){return `<div class="breadcrumb"><a href="#home">Academy</a><span>/</span><a href="#catalog">All courses</a><span>/</span><span>${c.title}</span></div><div class="detail-layout"><div>${heading(c.topic.toUpperCase(),c.title,c.desc)}${metadata(c)}<section><h2>What you’ll learn</h2><ul class="outcomes">${c.outcomes.map(t=>`<li>${t}</li>`).join('')}</ul></section><section><div class="section-head"><h2>Course syllabus</h2><span class="small">${c.lessons.length} lessons</span></div><ol class="syllabus">${c.lessons.map((l,i)=>`<li>${loggedIn?`<a class="lesson-link" href="#lesson/${c.id}/${i}">`:'<div class="lesson-link">'}<span class="lesson-index">${loggedIn&&state.done.includes(c.id+':'+i)?'✓':String(i+1).padStart(2,'0')}</span><span>${l[0]}</span><small>${c.duration/3} min</small>${loggedIn?'</a>':'</div>'}</li>`).join('')}</ol></section><section>${instructor()}</section><section><h2>Before you begin</h2><details open><summary>Prerequisites</summary><p>${c.prereq}. You can revisit earlier courses at any time.</p></details><details><summary>Completion criteria</summary><p>Read all three lessons and complete each knowledge check. Earn 10 learning coins per completed lesson and a course completion certificate.</p></details><details><summary>What does the certificate mean?</summary><p>It records completion of the sample course. It does not establish trading competence, profitability or eligibility for Axi Select. Learning coins have no cash value.</p></details></section></div><aside class="card enrol"><p class="eyebrow">YOUR COURSE</p><dl><div><dt>Access</dt><dd>Free</dd></div><div><dt>Level</dt><dd>${c.level}</dd></div><div><dt>Duration</dt><dd>${c.duration} minutes</dd></div><div><dt>Format</dt><dd>${c.format==='Video'?'Video outline':c.format}</dd></div></dl>${loggedIn?`<span class="small">${count(c)} of ${c.lessons.length} lessons complete</span><progress value="${count(c)}" max="${c.lessons.length}" aria-label="Course completion"></progress><a class="button" href="#lesson/${c.id}/${next(c)}">${count(c)===3?'Review course':state.started.includes(c.id)?'Resume course':'Start course'}</a><p class="small" style="margin:16px 0 0">${c.membersOnly?'Included with your Academy membership.':'No account required.'} Your progress stays in this browser.</p>`:selectNudge(c)}</aside></div>`;}
function learning(){let started=courses.filter(c=>state.started.includes(c.id)),completed=courses.filter(c=>count(c)===3),done=courses.reduce((s,c)=>s+count(c),0);let nextCourse=courses.find(c=>count(c)<3)||courses[0];return `${heading('MY LEARNING','Your learning, at a glance.','Pick up where you left off and see what to explore next.')}<div class="stats"><div><strong>${done}</strong><span>Lessons completed</span></div><div><strong>${done*10}</strong><span>Learning coins</span></div><div><strong>${completed.length}</strong><span>Certificates earned</span></div></div>${resume()}<section><div class="section-head"><h2>Your courses</h2><a class="text-link" href="#catalog">Browse courses</a></div>${started.length?started.map(c=>`<div class="learning-row"><div><h3><a href="#course/${c.id}">${c.title}</a></h3><p class="small">${c.topic} · ${c.level}</p></div><div><span class="small">${count(c)} of 3 lessons complete</span><progress value="${count(c)}" max="3" aria-label="${c.title} progress"></progress></div><a class="button secondary" href="#lesson/${c.id}/${next(c)}">${count(c)===3?'Review':'Continue'}</a></div>`).join(''):'<div class="empty"><h3>Your first lesson starts here</h3><p>Choose a course and your progress will appear in this space.</p><a class="button" href="#course/foundations">Explore foundations</a></div>'}</section><section><h2>Path progress</h2><div class="grid">${[['New to trading',['foundations','risk','markets']],['Build consistency',['plan','psychology']],['Understand Select',['select']]].map(([title,ids])=>{let total=ids.length*3,done=courses.filter(c=>ids.includes(c.id)).reduce((n,c)=>n+count(c),0);return `<div class="card"><h3>${title}</h3><progress value="${done}" max="${total}" aria-label="${title} path progress"></progress><span class="small">${done} of ${total} lessons completed</span></div>`;}).join('')}</div></section><section><h2>Recommended next</h2><div class="sample"><div><p class="eyebrow">${nextCourse.topic.toUpperCase()}</p><h3>${nextCourse.title}</h3><p>${nextCourse.desc}</p></div><a class="button secondary" href="#course/${nextCourse.id}">View course</a></div></section><section><h2>Learning milestones</h2><p class="small">Earn 10 coins for each lesson you complete. Coins recognise learning and have no cash value.</p>${completed.length?completed.map(c=>`<div class="recognition card"><div><strong>${c.title}</strong><p>Course complete · 3 lessons</p></div><a class="button secondary" style="margin-left:auto" href="#certificate/${c.id}">View certificate</a></div>`).join(''):'<div class="card"><h3>Your first certificate</h3><p style="margin-bottom:0">Complete all lessons and knowledge checks in a course to earn its completion certificate.</p></div>'}</section>`;}
function lesson(c,i){let l=c.lessons[i];if(!loggedIn)return `<div class="lesson-content"><div class="breadcrumb"><a href="#course/${c.id}">${c.title}</a><span>/</span><span>Lesson preview</span></div>${heading('LESSON PREVIEW',l[0],'')}<article class="reading"><p>${l[1]}</p><h2>A point to remember</h2><p>${l[2]}</p></article>${selectNudge(c)}<a href="#course/${c.id}">Back to course</a></div>`;let completed=state.done.includes(c.id+':'+i);return `<div class="lesson-content"><div class="breadcrumb"><a href="#course/${c.id}">${c.title}</a><span>/</span><span>Lesson ${i+1} of 3</span></div>${heading(`${c.format==='Video'?'VIDEO OUTLINE':'READING'} · ${c.duration/3} MIN`,l[0],'')}<progress value="i" max="3" aria-label="Lesson position"></progress><article class="reading">${c.format==='Video'?'<div class="callout"><strong>Sample lesson outline</strong><p style="margin:8px 0 0">The video recording has not been added yet. You can explore the lesson text below.</p></div>':''}<p>${l[1]}</p><h2>A point to remember</h2><p>${l[2]}</p><div class="callout"><strong>Pause and reflect</strong><p style="margin:8px 0 0">How would you explain this idea to someone new to trading? Note one question you would want to clarify before putting it into practice.</p></div></article><form id="quiz"><fieldset class="quiz"><legend>Check your understanding</legend><p>Which statement best reflects this lesson?</p><label><input type="radio" name="answer" value="a" required> Completing a lesson guarantees a successful trading outcome.</label><label><input type="radio" name="answer" value="b" required> ${c.id==='select'?'Learning progress and official program eligibility are separate.':'Understanding a concept helps you reason about a decision, but uncertainty remains.'}</label><button class="button secondary" type="submit">Check answer</button><p class="feedback" id="feedback" role="status">${completed?'You have already completed this lesson. You can review it again.':''}</p></fieldset></form><div class="lesson-bottom"><a class="button secondary" href="#course/${c.id}">Back to course</a><button class="button" id="complete" ${completed?'':'disabled'}>${completed?'Continue':'Complete lesson'}</button></div></div>`;}
function completeLesson(c,i){if(!loggedIn)return;let key=c.id+':'+i;if(!state.done.includes(key))state.done.push(key);save();notify('Lesson complete. You earned 10 learning coins.');location.hash=i<2?`lesson/${c.id}/${i+1}`:`certificate/${c.id}`;}

const webinars=[
 {id:'risk-workshop',title:'Understanding risk before your first trade',topic:'Risk management',date:'2026-10-14T11:00:00Z',minutes:45,instructor:'Alex Morgan',role:'Sample trading educator',level:'Beginner',summary:'A guided session on exposure, position size and planning for adverse outcomes.',agenda:['Recognise how exposure affects a position','Work through a sample risk scenario','Ask questions about the concepts covered']},
 {id:'chart-workshop',title:'Reading charts with a clear process',topic:'Market analysis',date:'2026-10-21T11:00:00Z',minutes:60,instructor:'Jamie Chen',role:'Sample market analysis educator',level:'Beginner',summary:'Learn to describe a chart, separate observations from assumptions and frame a market hypothesis.',agenda:['Read a chart across different timeframes','Describe a trend or range without assuming an outcome','Discuss a worked example and audience questions']},
 {id:'trading-journal',title:'Building a useful trading journal',topic:'Trading process',date:'2026-10-28T11:00:00Z',minutes:45,instructor:'Sam Taylor',role:'Sample trading process educator',level:'Intermediate',summary:'Explore how to record the reasoning behind a decision and review your process over time.',agenda:['Identify what to record in a journal','Separate decision quality from results','Choose a practical review routine']}
];
