webinars.push(
 {id:'risk-replay',kind:'recording',title:'Position sizing: a worked example',topic:'Risk management',date:'2026-09-30T11:00:00Z',minutes:42,instructor:'Alex Morgan',role:'Sample trading educator',level:'Beginner',summary:'Revisit a session on exposure, position size and planning for adverse price moves.',agenda:['Understand exposure in a sample position','Compare position sizes','Review common questions about risk'],recordingUrl:null},
 {id:'charts-replay',kind:'recording',title:'Chart reading fundamentals',topic:'Market analysis',date:'2026-09-23T11:00:00Z',minutes:55,instructor:'Jamie Chen',role:'Sample market analysis educator',level:'Beginner',summary:'Explore timeframes, trends and the difference between observation and prediction.',agenda:['Understand chart timeframes','Describe trends and ranges','Separate evidence from assumptions'],recordingUrl:null},
 {id:'journal-replay',kind:'recording',title:'Reviewing your trading decisions',topic:'Trading process',date:'2026-09-16T11:00:00Z',minutes:38,instructor:'Sam Taylor',role:'Sample trading process educator',level:'Intermediate',summary:'A practical introduction to reviewing a journal and identifying a process improvement.',agenda:['Record the reasoning behind a decision','Review the process separately from the result','Choose an improvement to practise'],recordingUrl:null}
);
function isRecording(w){return w.kind==='recording';}
const WEBINAR_KEY='axi-academy-webinars-v2';
let registrations={};
try{const saved=JSON.parse(localStorage.getItem(WEBINAR_KEY));if(saved&&typeof saved==='object'&&!Array.isArray(saved))registrations=saved;}catch(e){}
function webinarDate(w){return new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Singapore'}).format(new Date(w.date));}
function webinarTime(w){return new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit',hour12:true,timeZone:'Asia/Singapore'}).format(new Date(w.date))+' SGT (UTC+8)';}
function isRegistered(w){return loggedIn&&!!registrations[w.id];}
function webinarAction(w){return isRegistered(w)?`<span class="tag">Registered</span><button class="button secondary" data-cancel-webinar="${w.id}">Cancel registration</button>`:loggedIn?`<button class="button" data-join-webinar="${w.id}">Join webinar</button>`:`<a class="button" href="#join-academy/${w.id}">Join Axi Academy to attend</a>`;}
function filteredWebinars(topic='',view='all'){
 return webinars.filter(w=>(!topic||w.topic===topic)&&(view==='all'||(view==='recordings'?isRecording(w):!isRecording(w))));
}
function webinarRows(list,recorded){return list.length?`<div class="webinar-list">${list.map(w=>`<article class="card webinar-card"><div><p class="eyebrow">${w.topic.toUpperCase()} · ${recorded?'PAST WEBINAR':'UPCOMING'}</p><h3><a href="#webinar/${w.id}">${w.title}</a></h3><p>${w.summary}</p><div class="meta"><span>${recorded?'Recorded ':''}${webinarDate(w)}</span>${recorded?'':`<span>${webinarTime(w)}</span>`}<span>${w.minutes} min</span></div><p class="small">With ${w.instructor} · ${w.level}</p></div><div class="webinar-actions">${!recorded&&isRegistered(w)?`<span class="tag">Registered</span><button class="plain-button" data-cancel-webinar="${w.id}">Cancel registration</button>`:''}<a class="button secondary" href="#webinar/${w.id}">${recorded?(w.recordingUrl?'Watch recording':'View recording'):'View details'}</a>${recorded&&!w.recordingUrl?'<span class="small">Sample recording page</span>':''}</div></article>`).join('')}</div>`:`<div class="empty"><h3>No ${recorded?'recordings':'upcoming webinars'} for this topic</h3><p>Choose another topic or clear the filters.</p><button class="plain-button" data-clear-webinars>Clear filters</button></div>`;}
function webinarSections(topic,view){const list=filteredWebinars(topic,view),upcoming=list.filter(w=>!isRecording(w)).sort((a,b)=>new Date(a.date)-new Date(b.date)),past=list.filter(isRecording).sort((a,b)=>new Date(b.date)-new Date(a.date));return `${view!=='recordings'?`<section><div class="section-head"><h2>Upcoming webinars</h2><span class="small">${upcoming.length} sessions</span></div>${webinarRows(upcoming,false)}</section>`:''}${view!=='upcoming'?`<section><div class="section-head"><h2>Past webinars</h2><span class="small">${past.length} recordings</span></div>${webinarRows(past,true)}</section>`:''}`;}
function webinarList(){const params=new URLSearchParams(location.hash.split('?')[1]||''),topic=params.get('topic')||'',view=['all','upcoming','recordings'].includes(params.get('view'))?params.get('view'):'all';let mine=loggedIn?webinars.filter(w=>!isRecording(w)&&isRegistered(w)):[];return `${heading('WEBINAR LIBRARY','Learn live. Catch up anytime.','Explore upcoming sessions and revisit past webinars by topic.')}<p class="small">Sample schedule and fictional instructors. Times are in SGT (UTC+8). Recording pages are previews until approved videos are added.</p>${mine.length?`<section class="webinar-updates"><h2>Your webinar updates</h2>${mine.map(w=>`<div class="update-row"><div><strong>Registration confirmed</strong><p>${w.title}</p><span class="small">${webinarDate(w)} · ${webinarTime(w)}</span></div><a href="#webinar/${w.id}">View registration</a></div>`).join('')}<p class="small">Confirmations are saved in this browser. Email reminders and live joining links are not connected.</p></section>`:''}<section><form class="webinar-filters" id="webinar-filters" aria-label="Filter webinars"><div><label for="webinar-topic">Topic</label><select id="webinar-topic"><option value="">All topics</option>${[...new Set(webinars.map(w=>w.topic))].map(t=>`<option value="${esc(t)}" ${topic===t?'selected':''}>${t}</option>`).join('')}</select></div><div><label for="webinar-view">Session type</label><select id="webinar-view"><option value="all" ${view==='all'?'selected':''}>All webinars</option><option value="upcoming" ${view==='upcoming'?'selected':''}>Upcoming webinars</option><option value="recordings" ${view==='recordings'?'selected':''}>Past webinars / recordings</option></select></div><button class="plain-button" type="button" data-clear-webinars>Clear filters</button></form><p class="small" id="webinar-count" role="status">${filteredWebinars(topic,view).length} webinars found</p></section><div id="webinar-results">${webinarSections(topic,view)}</div>`;}
function filterWebinarLibrary(clear=false){const topic=document.querySelector('#webinar-topic'),view=document.querySelector('#webinar-view');if(!topic||!view)return;if(clear){topic.value='';view.value='all';}const params=new URLSearchParams();if(topic.value)params.set('topic',topic.value);if(view.value!=='all')params.set('view',view.value);history.replaceState(null,'','#webinars'+(params.size?'?'+params:''));document.querySelector('#webinar-results').innerHTML=webinarSections(topic.value,view.value);document.querySelector('#webinar-count').textContent=filteredWebinars(topic.value,view.value).length+' webinars found';bindWebinarClear();document.querySelectorAll('#webinar-results [data-cancel-webinar]').forEach(b=>b.addEventListener('click',()=>cancelWebinar(b.dataset.cancelWebinar)));}
function bindWebinarClear(){document.querySelectorAll('[data-clear-webinars]').forEach(b=>b.onclick=()=>filterWebinarLibrary(true));}
function recordingDetail(w){return `<div class="breadcrumb"><a href="#webinars?view=recordings">Past webinars</a><span>/</span><span>${w.topic}</span></div><div class="recording-detail">${heading('PAST WEBINAR',w.title,w.summary)}<div class="meta"><span>Recorded ${webinarDate(w)}</span><span>${w.minutes} minutes</span><span>${w.level}</span></div>${w.recordingUrl?`<video class="webinar-player" controls preload="metadata" aria-label="${esc(w.title)} recording"><source src="${esc(w.recordingUrl)}" type="video/mp4">Your browser does not support video playback.</video>`:`<div class="recording-placeholder"><p class="eyebrow">WEBINAR RECORDING</p><h2>Recording preview</h2><p>The recorded video has not been added to this prototype.</p><span class="small">${w.minutes} min · ${w.instructor}</span></div>`}<section><h2>In this session</h2><ul class="outcomes">${w.agenda.map(a=>`<li>${a}</li>`).join('')}</ul></section><section><h2>Your instructor</h2><div class="instructor"><div class="avatar" aria-hidden="true">${w.instructor.split(' ').map(x=>x[0]).join('')}</div><div><h3>${w.instructor}</h3><p>${w.role}</p><p class="small">Fictional instructor for this sample event.</p></div></div></section><section><a class="button secondary" href="#webinars?view=recordings">Browse recordings</a></section></div>`;}
function webinarDetail(w){if(isRecording(w))return recordingDetail(w);return `<div class="breadcrumb"><a href="#webinars">Webinars</a><span>/</span><span>${w.topic}</span></div><div class="detail-layout"><div>${heading('LIVE WEBINAR',w.title,w.summary)}<div class="meta"><span>${webinarDate(w)}</span><span>${webinarTime(w)}</span><span>${w.minutes} minutes</span></div><section><h2>What we’ll cover</h2><ul class="outcomes">${w.agenda.map(a=>`<li>${a}</li>`).join('')}</ul></section><section><h2>Your instructor</h2><div class="instructor"><div class="avatar" aria-hidden="true">${w.instructor.split(' ').map(x=>x[0]).join('')}</div><div><h3>${w.instructor}</h3><p>${w.role}</p><p class="small">Fictional profile for this prototype.</p></div></div></section><section><h2>How to attend</h2><p>Join Axi Academy, then register for the session. Your registration confirmation appears in your webinar updates.</p><p class="small">This is a sample event. Live access, email reminders and schedule-change notifications require a connected webinar service.</p></section></div><aside class="card enrol webinar-registration"><p class="eyebrow">${isRegistered(w)?'YOUR REGISTRATION':'SESSION DETAILS'}</p><dl><div><dt>Date</dt><dd>${webinarDate(w)}</dd></div><div><dt>Time</dt><dd>${webinarTime(w)}</dd></div><div><dt>Duration</dt><dd>${w.minutes} minutes</dd></div><div><dt>Instructor</dt><dd>${w.instructor}</dd></div><div><dt>Access</dt><dd>Academy members</dd></div></dl>${webinarAction(w)}${isRegistered(w)?`<div class="registration-confirmation" role="status"><h3>You’re registered</h3><p>Your place is recorded in this demo. You can find this confirmation in your webinar updates.</p><a href="#webinars">View webinar updates</a></div>`:`<p class="small" style="margin-top:16px">${loggedIn?'Register to add this session to your webinar updates.':'Already a member?'} ${loggedIn?'':`<button class="plain-button" data-webinar-login="${w.id}">Login</button>`}</p>`}</aside></div>`;}
function joinAcademy(w){return `<div class="join-academy">${heading('AXI ACADEMY','Join the Academy to attend','Become a member to register for webinars and keep your learning in one place.')}<div class="card"><p class="eyebrow">YOUR SELECTED WEBINAR</p><h2>${w.title}</h2><p>${webinarDate(w)} · ${webinarTime(w)}</p><p>With ${w.instructor}</p><button class="button" data-create-academy="${w.id}">Join Axi Academy</button><p class="small" style="margin-top:16px">Demo signup: this opens a sample member account. No personal details or real account are created.</p><p class="small">Already a member? <button class="plain-button" data-webinar-login="${w.id}">Login</button></p></div><p style="margin-top:24px"><a href="#webinar/${w.id}">Back to webinar details</a></p></div>`;}
function webinarLogin(id){login();history.replaceState(null,'','#webinar/'+id);render();}
function joinWebinar(id){const w=webinars.find(w=>w.id===id);if(!w||isRecording(w))return;if(!loggedIn){location.hash='join-academy/'+id;return;}if(!registrations[id])registrations[id]={joinedAt:new Date().toISOString()};try{localStorage.setItem(WEBINAR_KEY,JSON.stringify(registrations));}catch(e){notify('Your registration lasts for this visit only. Browser storage is unavailable.');}render();}
function cancelWebinar(id){
 if(!loggedIn||!registrations[id])return;
 delete registrations[id];
 let persisted=true;
 try{localStorage.setItem(WEBINAR_KEY,JSON.stringify(registrations));}catch(e){persisted=false;}
 render();
 notify(persisted?'Registration cancelled. You can join again at any time.':'Registration cancelled for this visit. Browser storage could not be updated.');
}
function bindWebinars(){document.querySelectorAll('[data-cancel-webinar]').forEach(b=>b.addEventListener('click',()=>cancelWebinar(b.dataset.cancelWebinar)));bindWebinarClear();document.querySelector('#webinar-filters')?.addEventListener('submit',e=>e.preventDefault());document.querySelector('#webinar-topic')?.addEventListener('change',()=>filterWebinarLibrary());document.querySelector('#webinar-view')?.addEventListener('change',()=>filterWebinarLibrary());document.querySelectorAll('[data-join-webinar]').forEach(b=>b.addEventListener('click',()=>joinWebinar(b.dataset.joinWebinar)));document.querySelectorAll('[data-webinar-login]').forEach(b=>b.addEventListener('click',()=>webinarLogin(b.dataset.webinarLogin)));document.querySelectorAll('[data-create-academy]').forEach(b=>b.addEventListener('click',()=>webinarLogin(b.dataset.createAcademy)));}

function render(){let raw=location.hash.slice(1)||'home',parts=raw.split('?')[0].split('/'),page=parts[0],c=courses.find(c=>c.id===parts[1]),params=new URLSearchParams(raw.split('?')[1]||'');if(c&&c.membersOnly&&!loggedIn&&['course','lesson','certificate'].includes(page)){main.innerHTML=`${heading('ACADEMY MEMBERS','More learning with your membership.','Login to explore this course and save your progress.')}<button class="button" id="member-course-login">Login to view course</button>`;document.querySelector('#member-course-login').addEventListener('click',()=>{login();history.replaceState(null,'','#course/'+c.id);render();});}
else if(page==='lesson'&&c&&!loggedIn){const i=Number(parts[2]);main.innerHTML=Number.isInteger(i)&&i>=0&&i<c.lessons.length?lesson(c,i):detail(c);}
else if(page==='lesson'&&c){let i=Number(parts[2]);if(!Number.isInteger(i)||i<0||i>=c.lessons.length){location.hash='course/'+c.id;return;}if(!state.started.includes(c.id))state.started.push(c.id);state.last={course:c.id,lesson:i};save();main.innerHTML=lesson(c,i);document.querySelector('progress').value=i+1;document.querySelector('#quiz').addEventListener('submit',e=>{e.preventDefault();let answer=new FormData(e.target).get('answer');document.querySelector('#feedback').textContent=answer==='b'?'Correct. Learning supports informed decisions, while uncertainty and applicable requirements remain.':'Not quite. A lesson cannot guarantee an outcome. Revisit the point above and try again.';document.querySelector('#complete').disabled=answer!=='b'&&!state.done.includes(c.id+':'+i);});document.querySelector('#complete').onclick=()=>{if(state.done.includes(c.id+':'+i)){location.hash=i<2?`lesson/${c.id}/${i+1}`:`learning`;}else completeLesson(c,i);};}
else if(page==='join-select'&&c){main.innerHTML=`${heading('AXI SELECT','Continue your learning journey','Join to keep your learning progress and return to your lessons.')}<div class="card"><h2>Sample onboarding</h2><p>This prototype demonstrates the member learning experience. It does not create an Axi Select account or verify eligibility.</p><button class="button" data-course-login="${c.id}">Continue to demo member view</button></div>`;}
else if(page==='select-competition'){main.innerHTML=loggedIn?competitionPage():`${heading('AXI SELECT','Competition information','Login to view the member overview.')}<button class="button" id="page-login">Login</button>`;}
else if(page==='webinars')main.innerHTML=webinarList();
else if(page==='webinar'&&webinars.some(w=>w.id===parts[1]))main.innerHTML=webinarDetail(webinars.find(w=>w.id===parts[1]));
else if(page==='join-academy'&&webinars.some(w=>w.id===parts[1]))main.innerHTML=loggedIn?webinarDetail(webinars.find(w=>w.id===parts[1])):joinAcademy(webinars.find(w=>w.id===parts[1]));
else if(page==='course'&&c)main.innerHTML=detail(c);
else if(page==='learning')main.innerHTML=loggedIn?learning():`${heading('MY LEARNING','Your learning starts with a login.','Open the demo user view to see saved progress and continue learning.')}<button class="button" id="page-login">Login</button>`;
else if(page==='catalog'){main.innerHTML=catalog(params);filterCourses();document.querySelector('#filters').onsubmit=e=>e.preventDefault();document.querySelector('#search').oninput=filterCourses;document.querySelector('#topic').onchange=filterCourses;document.querySelector('#level').onchange=filterCourses;document.querySelector('#reset-filters').onclick=()=>{history.replaceState(null,'','#catalog');document.querySelector('#search').value='';document.querySelector('#topic').value='';document.querySelector('#level').value='';filterCourses();};}
else if(page==='certificate'&&c&&count(c)===3)main.innerHTML=`${heading('LEARNING MILESTONE','Course completed.','You have completed the sample lessons and knowledge checks.')}<div class="certificate"><p class="eyebrow">AXI ACADEMY · SAMPLE CERTIFICATE</p><h2>${c.title}</h2><p>3 lessons completed · 30 learning coins earned</p><p class="small">This certificate records educational completion only.<br>It does not establish trading competence or Axi Select eligibility.</p></div><a class="button" href="#learning">Back to my learning</a>`;
else if(page==='home')main.innerHTML=home();else main.innerHTML=`${heading('PAGE NOT FOUND','Let’s get you back to learning.','This page or certificate is not available.')}<a class="button" href="#home">Academy homepage</a>`;
bindWebinars();document.querySelectorAll('[data-course-login]').forEach(b=>b.addEventListener('click',()=>courseLogin(b.dataset.courseLogin)));
document.querySelector('#login-toggle').textContent=loggedIn?'Log out':'Login';document.querySelector('#account-label').hidden=!loggedIn;document.querySelector('[data-nav=learning]').hidden=!loggedIn;document.querySelector('#page-login')?.addEventListener('click',login);
document.querySelectorAll('[data-nav]').forEach(a=>{let active=a.dataset.nav===(page==='course'||page==='lesson'?'catalog':page==='certificate'?'learning':page==='select-competition'?'home':['webinar','join-academy'].includes(page)?'webinars':page);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});document.title=(c?c.title:page==='catalog'?'All courses':page==='learning'?'My learning':['webinars','webinar','join-academy'].includes(page)?'Webinars':'Overview')+' | Axi Academy';window.scrollTo(0,0);main.focus({preventScroll:true});}
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();main.scrollIntoView();});
document.querySelector('#login-toggle').addEventListener('click',()=>{if(loggedIn){logout();return;}const parts=location.hash.slice(1).split('/');if(['webinar','join-academy'].includes(parts[0])&&webinars.some(w=>w.id===parts[1]))webinarLogin(parts[1]);else login();});
window.addEventListener('hashchange',render);render();if(!storageAvailable)notify('Saved progress is unavailable. Your progress will last for this visit only.');
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'search_academy_courses',description:'Search the Academy course library by title, topic or description and show matching courses.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input.query!=='string'||input.query.length>200)throw new Error('Provide a search query up to 200 characters.');history.replaceState(null,'','#catalog?q='+encodeURIComponent(input.query));render();return {courses:availableCourses().filter(c=>(c.title+' '+c.topic+' '+c.desc).toLowerCase().includes(input.query.toLowerCase())).map(c=>({id:c.id,title:c.title}))};}})).catch(()=>{});}catch(e){}}
